import { useState } from "react";
import { useResults } from "../context/ResultsContext";
import { useNavigate } from "react-router-dom";
import { exportResults } from "../api";

export default function Results() {
  const { results } = useResults();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("All");

  if (!results || results.length === 0) {
    return (
      <div className="page">
        <div className="container">
          <p>No results yet</p>
        </div>
      </div>
    );
  }

  const filteredResults =
    activeTab === "All"
      ? results
      : results.filter((r) => r.decision === activeTab);

  const getBadgeClass = (decision) => {
    if (decision === "Shortlisted") return "badge shortlisted";
    if (decision === "Rejected") return "badge rejected";
    return "badge review";
  };

  const handleExport = async () => {
    try {
      const blob = await exportResults();
      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "resume_screening_results.csv";
      a.click();

      window.URL.revokeObjectURL(url);
    } catch (err) {
      alert("Failed to export CSV");
    }
  };

  return (
    <div className="page">
      <div className="container">
        <h2>Screening Results</h2>

        <div
          style={{
            display: "flex",
            justifyContent: "flex-end",
            marginBottom: "16px",
          }}
        >
          <button onClick={handleExport}>Download CSV</button>
        </div>

        <div style={{ display: "flex", gap: "12px", marginBottom: "16px" }}>
          {["All", "Shortlisted", "Rejected"].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              style={{
                fontWeight: activeTab === tab ? "bold" : "normal",
              }}
            >
              {tab}
            </button>
          ))}
        </div>

        {filteredResults.map((r, index) => (
          <div
            key={index}
            className="card"
            style={{ cursor: "pointer" }}
            onClick={() => navigate(`/candidate/${index}`)}
          >
            <div style={{ display: "flex", justifyContent: "space-between" }}>
              <h4>{r.filename}</h4>
              <span className={getBadgeClass(r.decision)}>{r.decision}</span>
            </div>

            <p>Match Score: {r.final_score}%</p>

            <div>
              <strong>Strengths</strong>
              <ul>
                {r.ai?.strengths?.map((s, i) => (
                  <li key={i}>{s}</li>
                ))}
              </ul>
            </div>

            <div>
              <strong>Red Flags</strong>
              <ul>
                {r.ai?.red_flags?.map((rf, i) => (
                  <li key={i}>{rf}</li>
                ))}
              </ul>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
